<script setup lang="ts">
import { ref } from "vue";
import { http } from "@/utils/http";
type Dictionary = Record<string, any>; const rows = ref<Dictionary[]>([]); const selected = ref<Dictionary | null>(null); const loading = ref(false); const error = ref("");
async function load() { loading.value = true; try { const result: any = await http.get("/platform/dictionaries"); rows.value = Array.isArray(result) ? result : (result?.content || result?.items || []); selected.value = rows.value[0] || null; } catch (e: any) { error.value = e?.response?.data?.detail || "受控字典接口尚未接入"; } finally { loading.value = false; } }
load();
</script>
<template><main class="p-4 md:p-6"><div class="flex justify-between items-start mb-6"><div><h1 class="text-2xl font-semibold">数据字典</h1><p class="mt-1 text-[var(--el-text-color-secondary)]">仅管理产品明确设计为运行时可配置的受控字典，不是通用 SQL 表编辑器。</p></div><el-button :loading="loading" @click="load">刷新</el-button></div><el-alert v-if="error" :title="error" type="warning" show-icon :closable="false" class="mb-4"/><el-skeleton v-if="loading" :rows="8" animated/><div v-else class="grid grid-cols-1 md:grid-cols-3 gap-5"><el-card shadow="never"><template #header>Dictionary</template><el-empty v-if="!rows.length" description="暂无字典目录"/><div v-for="item in rows" :key="item.id || item.key" class="p-3 rounded cursor-pointer" :class="selected === item ? 'bg-[var(--el-fill-color-light)]' : ''" @click="selected = item"><div class="font-medium">{{ item.name || item.key }}</div><div class="text-xs text-[var(--el-text-color-secondary)] mt-1">{{ item.entryCount ?? 0 }} entries · {{ item.source || 'System' }}</div></div></el-card><el-card shadow="never" class="md:col-span-2"><template #header><div class="flex justify-between"><span>{{ selected?.name || '选择一个字典' }}</span><el-button :disabled="!selected">新增 Entry</el-button></div></template><el-empty v-if="!selected" description="选择左侧字典查看 Entry"/><template v-else><el-table :data="selected.entries || []" stripe><el-table-column prop="value" label="Value / Key" min-width="180"/><el-table-column prop="label" label="Display Label" min-width="180"/><el-table-column prop="description" label="描述" min-width="220"/><el-table-column prop="enabled" label="启用" width="100"/><el-table-column prop="sortOrder" label="顺序" width="90"/></el-table><el-alert title="System-owned Entry 默认只读；禁用不会影响已有引用。" type="info" show-icon class="mt-4"/></template></el-card></div></main></template>
